def now():
    return time.strftime("%Y-%m-%dT%H:%M:%S%z")


def digest(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def clean(value):
    if isinstance(value, dict):
        return {str(k): clean(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [clean(v) for v in value]
    if hasattr(value, "tolist"):
        return clean(value.tolist())
    if isinstance(value, float) and not math.isfinite(value):
        return None
    return value


def read(path, default=None):
    path = Path(path)
    if not path.exists():
        return default
    if path.is_symlink():
        raise RuntimeError(f"状态文件是重定向，保留原文件：{path}")
    return json.loads(path.read_text(encoding="utf-8-sig"))


def save(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.is_symlink():
        raise RuntimeError(f"输出文件是重定向，停止覆盖：{path}")
    temporary = path.with_name(path.name + f".pending_{os.getpid()}")
    temporary.write_text(json.dumps(clean(value), ensure_ascii=False, indent=2, allow_nan=False), encoding="utf-8")
    os.replace(temporary, path)


def tasks():
    # 优先补原环境；每个环境内按种子配对随机排列开关，不按成绩安排顺序。
    rng = random.Random(20261104)
    rows = []
    for environment in ("E0", "E1"):
        for seed in SEEDS:
            modes = ["ON", "OFF"]
            rng.shuffle(modes)
            for mode in modes:
                rows.append(dict(
                    id=f"STIN__{environment}__K3__LQ__STIN_{mode}__s{seed}",
                    stage="STIN_COMPLETION", environment=environment, k=3,
                    fleet=12 if environment == "E1" else None, seed=seed,
                    arm="STIN_" + mode, credit_arm="JOINT", stin_mode=mode,
                    control="LQ", reward_mode="PT_POST", time_mode="RAW",
                    variant="M0_BASE", method="SINGLE__M0_BASE", timing=True,
                    batch=True, network="TRANSFORMER", gamma=.99, run_order=len(rows) + 1,
                ))
    assert len(rows) == 16 and len(rows) * STEPS == NEW_STEPS and STEPS % 20480 == 0
    return rows


def legacy_ids():
    return [f"CORE__E1__K3__J3__STIN_{mode}__s{seed}" for seed in SEEDS for mode in ("ON", "OFF")]


def legacy_records(legacy_root, archive):
    """旧结果只读；服务器目录优先，目录缺失时可核对DATAONLY中的记录。"""
    wanted = {"SUITE_PLAN.json"}
    fields = ("TRAIN_END.json", "STAGE_EVAL_END.json", "MODEL_MANIFEST.json", "RESULT.json", "NEW_ORDER_CONFIRMATION.json")
    for ident in legacy_ids():
        wanted.update(f"cells/{ident}/{name}" for name in fields)
    records = {}
    hashes = {}
    for rel in sorted(wanted):
        path = legacy_root / rel
        if path.is_file():
            if path.is_symlink() or not path.resolve().is_relative_to(legacy_root.resolve()):
                raise RuntimeError(f"旧记录路径离开实验目录：{path}")
            raw = path.read_bytes()
            records[rel] = json.loads(raw.decode("utf-8-sig"))
            hashes[rel] = hashlib.sha256(raw).hexdigest()
    # 只读JSON，不解压、不执行、不加载压缩包里的模型。
    missing = wanted - records.keys()
    if missing and archive.is_file():
        if archive.is_symlink():
            raise RuntimeError("旧数据包是重定向，不读取")
        prefix = LEGACY_NAME + "/"
        with tarfile.open(archive, "r:gz") as tar:
            for member in tar:
                rel = member.name.removeprefix(prefix)
                if not member.name.startswith(prefix) or rel not in missing:
                    continue
                if not member.isfile() or member.size > 16 * 1024 * 1024:
                    raise RuntimeError("旧包中的记录不是有界普通文件")
                raw = tar.extractfile(member).read()
                records[rel] = json.loads(raw.decode("utf-8-sig"))
                hashes[rel] = hashlib.sha256(raw).hexdigest()
    return records, hashes


def audit_legacy(legacy_root, archive):
    records, hashes = legacy_records(legacy_root, archive)
    suite = records.get("SUITE_PLAN.json", {})
    suite_ok = suite.get("script_sha256") == LEGACY_ENTRY_SHA and suite.get("frozen_stin_sha256") == STIN_SHA
    rows = []
    for ident in legacy_ids():
        prefix = "cells/" + ident + "/"
        train = records.get(prefix + "TRAIN_END.json", {})
        end = records.get(prefix + "STAGE_EVAL_END.json", {})
        manifest = records.get(prefix + "MODEL_MANIFEST.json", {})
        task = manifest.get("task", {})
        expected_mode = "OFF" if "__STIN_OFF__" in ident else "ON"
        expected_seed = int(ident.rsplit("s", 1)[-1])
        match = (suite_ok and task.get("id") == ident and task.get("environment") == "E1"
                 and task.get("control") == "J3" and task.get("k") == 3 and task.get("fleet") == 12
                 and task.get("seed") == expected_seed and task.get("stin_mode") == expected_mode
                 and task.get("reward_mode") == "PT_POST" and task.get("gamma") == .99
                 and task.get("timing") is True and task.get("batch") is True
                 and manifest.get("stin_source_sha256") == STIN_SHA
                 and manifest.get("config", {}).get("actual_steps") == STEPS)
        result = records.get(prefix + "RESULT.json")
        confirmation = records.get(prefix + "NEW_ORDER_CONFIRMATION.json")
        complete = bool(match and train.get("steps") == STEPS and end.get("status") == "COMPLETE"
                        and end.get("step") == STEPS and end.get("weights_unchanged") is True
                        and result and confirmation and len(confirmation.get("episodes", [])) == 4)
        folder = legacy_root / "cells" / ident
        marker = folder / "checkpoints" / f"step_{STEPS:09d}.json"
        models_present = False
        if marker.is_file():
            cp = read(marker)
            artifacts = [marker.parent / Path(cp[name]).name for name in ("model", "vecnorm")]
            models_present = cp.get("step") == STEPS and all(
                p.is_file() and not p.is_symlink() and p.resolve().is_relative_to(folder.resolve()) for p in artifacts)
        rows.append(dict(id=ident, environment="E1", control="J3", seed=expected_seed,
                         stin_mode=expected_mode, protocol_match=bool(match), records_complete=complete,
                         trained_steps=train.get("steps", 0), final_models_present=models_present,
                         source="旧目录或DATAONLY只读核验；不重训、不补造旧结果"))
    audit = dict(time=now(), source_root=str(legacy_root), source_archive=str(archive), expected=8,
                 complete=sum(r["records_complete"] for r in rows),
                 final_models_present=sum(r["final_models_present"] for r in rows), rows=rows,
                 record_sha256=hashes, records=records,
                 boundary="完整周期E1的J3开关各四种子；不等于E1单侧也已完成，不代表全部机场规模。")
    return audit


def load_stage():
    raw = zlib.decompress(base64.b85decode(SEALED_STAGE_B85))
    if hashlib.sha256(raw).hexdigest() != SEALED_STAGE_SHA:
        raise RuntimeError("封存STIN运行时hash不符，不执行")
    tree = ast.parse(raw.decode("utf-8-sig"))
    tree.body = [n for n in tree.body if not (isinstance(n, ast.If) and isinstance(n.test, ast.Compare)
                 and isinstance(n.test.left, ast.Name) and n.test.left.id == "__name__")]
    module = types.ModuleType("stin_completion_sealed_stage")
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[module.__name__] = module
    exec(compile(tree, "<sealed_stin_stage_without_entry>", "exec"), module.__dict__)
    import cloudpickle
    cloudpickle.register_pickle_by_value(module)
    module.ROOT_NAME = ROOT_NAME
    module.VERSION = VERSION
    module.PLANNED_STEPS = NEW_STEPS
    module.CAP = CAP
    module.PROJECT = PROJECT
    return module


def runtime():
    stage = load_stage()
    module = stage.runtime()
    original_manifest = module.attr_update_manifest
    def manifest(folder, task):
        original_manifest(folder, task)
        path = Path(folder) / "MODEL_MANIFEST.json"
        record = read(path)
        record.update(
            main_question="原E0与完整周期E1中，单侧控制下公开源码STIN开关的匹配消融。",
            auxiliary="沿用旧60M共同学习合同；单侧飞机无可学习选择，影子头不参与actor更新。",
            no_novelty_claim="只补齐STIN证据，不新增方法，不改奖励、物理和信息。",
            environment_boundary="E0为已有源环境物理；PT_POST与dropout=0为既有受控合同，不冒称原论文表格数字复刻。",
            diagnostic_scope="保留既有整场评估、最终事件轨迹；本次不新增深分支或热点适配诊断。",
            sealed_stage_sha256=SEALED_STAGE_SHA,
        )
        save(path, record)
    module.attr_update_manifest = manifest
    return stage, module


def train_complete(folder, task):
    record = read(folder / "TRAIN_END.json")
    if record is None:
        return False
    if record.get("steps") != STEPS or record.get("task") != task:
        raise RuntimeError(f"已有训练结束记录不匹配，保留待查：{folder.name}")
    cp = read(folder / "checkpoints" / f"step_{STEPS:09d}.json")
    if not cp or cp.get("step") != STEPS:
        raise RuntimeError(f"已有满训记录缺最终指针，不自动重训：{folder.name}")
    for key in ("model", "vecnorm"):
        path = folder / "checkpoints" / Path(cp[key]).name
        if not path.is_file() or path.is_symlink() or not path.resolve().is_relative_to(folder.resolve()):
            raise RuntimeError(f"已有满训记录缺最终模型配套，不自动重训：{path}")
    return True


def eval_complete(folder):
    end = read(folder / "STAGE_EVAL_END.json", {})
    result = read(folder / "RESULT.json", {})
    confirmation = read(folder / "NEW_ORDER_CONFIRMATION.json", {})
    return bool(end.get("status") == "COMPLETE" and end.get("step") == STEPS
                and end.get("weights_unchanged") is True
                and result.get("main_late_confirmation") and result.get("final_confirmation")
                and confirmation.get("checkpoint") == STEPS and len(confirmation.get("episodes", [])) == 4)


def evaluate(stage, module, task, root, config):
    # 原评估函数中的整场曲线和四条确认顺序原样保留，仅不额外启动深分支诊断。
    stage.quality_eval = lambda *args, **kwargs: None
    stage.evaluate(module, task, root, config)
    save(root / "cells" / task["id"] / "STIN_COMPLETION_EVAL_SCOPE.json",
         dict(full_replay=True, new_deep_branches=False, weights_unchanged=True, time=now()))


def resource_check(root, device, min_free):
    free = shutil.disk_usage(root).free / 1024**3
    if free < min_free:
        raise RuntimeError(f"磁盘仅余{free:.1f}GiB，保留已有恢复件后停止")
    record = dict(time=now(), device=device, disk_free_gib=free)
    if device == "cuda":
        if not os.environ.get("CUDA_VISIBLE_DEVICES"):
            raise RuntimeError("请显式指定CUDA_VISIBLE_DEVICES，不自动选择共享GPU")
        result = subprocess.run(["nvidia-smi", "--query-gpu=index,memory.free,utilization.gpu",
                                 "--format=csv,noheader,nounits"], capture_output=True, text=True)
        record.update(nvidia_smi=result.stdout, returncode=result.returncode)
        if result.returncode:
            raise RuntimeError("无法读取GPU，不安装驱动、不静默改CPU")
    # GPU瞬时利用率只记账，不再因为一个利用率阈值把本套实验退出。
    save(root / "RESOURCE_SNAPSHOT.json", record)


def aggregate(module, root, task_list, legacy):
    status = []
    rows = []
    for task in task_list:
        folder = root / "cells" / task["id"]
        error = None
        try:
            trained = train_complete(folder, task)
            evaluated = trained and eval_complete(folder)
            live = read(folder / "LIVE.json", {})
        except Exception as exc:
            # 单格损坏只标待查，不能使其他种子的训练与进度汇总一起退出。
            trained, evaluated, live = False, False, {}
            error = f"{type(exc).__name__}: {exc}"
        status.append(dict(task=task, trained=trained, evaluated=evaluated,
                           steps=STEPS if trained else live.get("steps", 0),
                           failed=bool(error or list(folder.glob("FAILED_*.json"))) and not evaluated,
                           error=error))
        result = read(folder / "RESULT.json") if evaluated else None
        if result and evaluated:
            confirmation = read(folder / "NEW_ORDER_CONFIRMATION.json")
            episodes = confirmation["episodes"]
            rows.append(dict(**task, origin="新增匹配单侧消融", late_rpt=result["main_late_confirmation"]["rpt"],
                             final_rpt=result["final_confirmation"]["rpt"],
                             final_completion=result["final_confirmation"]["completion"],
                             new_order_rpt=sum(e["restricted_person_time_per_generated"] for e in episodes) / len(episodes),
                             new_order_completion=sum(e["completion"] for e in episodes) / len(episodes)))
    # 只核对同环境、同种子的两臂初始策略；不声称不同环境初始状态相同。
    initial = {}
    for task in task_list:
        entry = read(root / "cells" / task["id"] / "INITIAL_POLICY_SHA.json")
        if entry:
            initial.setdefault((task["environment"], task["seed"]), set()).add(entry["sha256"])
    if any(len(values) > 1 for values in initial.values()):
        raise RuntimeError("同环境同种子的STIN开关初始权重不一致")
    measured, upper = module.budget_account(root)
    progress = dict(total=16, trained=sum(r["trained"] for r in status),
                    evaluated=sum(r["evaluated"] for r in status), failed=sum(r["failed"] for r in status),
                    completed_training_transitions=sum(r["steps"] for r in status if r["trained"]),
                    measured_training_work=measured, interrupted_unlogged_upper_bound=upper,
                    planned_actual_budget=NEW_STEPS, budget_cap=CAP,
                    legacy_joint_expected=8, legacy_joint_records_complete=legacy["complete"],
                    legacy_joint_models_present=legacy["final_models_present"], time=now())
    module.save_csv(root / "RUN_STATUS.csv", status)
    module.save_csv(root / "MODEL_RESULTS.csv", rows)
    paired = []
    indexed = {(r["environment"], r["seed"], r["stin_mode"]): r for r in rows}
    for environment in ("E0", "E1"):
        for seed in SEEDS:
            on = indexed.get((environment, seed, "ON"))
            off = indexed.get((environment, seed, "OFF"))
            if on and off:
                paired.append(dict(environment=environment, control="LQ", seed=seed,
                                   contrast="OFF减ON，负值表示关闭成本更低",
                                   late_delta=off["late_rpt"] - on["late_rpt"],
                                   new_order_delta=off["new_order_rpt"] - on["new_order_rpt"],
                                   completion_delta=off["new_order_completion"] - on["new_order_completion"]))
    module.save_csv(root / "PAIRED_EFFECTS.csv", paired)
    save(root / "progress.json", progress)
    save(root / "STIN_COVERAGE.json", dict(
        expected=dict(E0_LQ=8, E1_LQ=8, E1_J3=8),
        completed=dict(E0_LQ=sum(r["evaluated"] for r in status if r["task"]["environment"] == "E0"),
                       E1_LQ=sum(r["evaluated"] for r in status if r["task"]["environment"] == "E1"),
                       E1_J3=legacy["complete"]),
        boundary="只覆盖K3、四训练种子和公开源码同一STIN开关；E0没有真实飞机联合动作，不生成E0-J3。",
        legacy_retraining=False, legacy_replay_models_present=legacy["final_models_present"], time=now()))
    return progress


def pack(root, task_list, legacy, include_models):
    output = PROJECT / "experiment_archives"
    output.mkdir(exist_ok=True)
    for kind in (["DATAONLY", "FINAL_REPLAY_MODELS"] if include_models else ["DATAONLY"]):
        target = output / f"{ROOT_NAME}_{kind}.tar.gz"
        if target.is_symlink():
            raise RuntimeError("结果包路径重定向，不覆盖")
        if target.exists():
            with tarfile.open(target, "r:gz") as old:
                prior = json.load(old.extractfile(ROOT_NAME + "/SUITE_PLAN.json"))
            if prior.get("script_sha256") != digest(__file__):
                raise RuntimeError("同名旧包不是本套代码合同，不覆盖")
        temporary = target.with_name(target.name + ".pending")
        with tarfile.open(temporary, "w:gz") as tar:
            tar.add(__file__, arcname=ROOT_NAME + "/ENTRYPOINT.py", recursive=False)
            if kind == "DATAONLY":
                for path in sorted(root.rglob("*")):
                    if path.is_file() and not path.is_symlink() and path.suffix.lower() in (".json", ".csv", ".log", ".txt", ".md") and ".pending" not in path.name:
                        tar.add(path, arcname=ROOT_NAME + "/" + path.relative_to(root).as_posix(), recursive=False)
            else:
                for path in [root / "SUITE_PLAN.json", root / "STIN_COVERAGE.json", root / "LEGACY_JOINT_AUDIT.json", root / "END.json"] + list((root / "bank").glob("*.csv")):
                    if path.is_file():
                        tar.add(path, arcname=ROOT_NAME + "/" + path.relative_to(root).as_posix(), recursive=False)
                for task in task_list:
                    folder = root / "cells" / task["id"]
                    if not train_complete(folder, task):
                        raise RuntimeError("新单侧格缺最终模型，不生成完整回放包")
                    marker = folder / "checkpoints" / f"step_{STEPS:09d}.json"
                    cp = read(marker)
                    paths = [marker, folder / "TASK.json", folder / "TRAIN_END.json", folder / "MODEL_MANIFEST.json"]
                    paths += [marker.parent / Path(cp[key]).name for key in ("model", "vecnorm")]
                    for path in paths:
                        if not path.is_file() or path.is_symlink() or not path.resolve().is_relative_to(root.resolve()):
                            raise RuntimeError(f"最终模型配套路径不合法：{path}")
                        tar.add(path, arcname=ROOT_NAME + "/" + path.relative_to(root).as_posix(), recursive=False)
        os.replace(temporary, target)
        save(root / f"{kind}_PACKAGE.json", dict(path=str(target), sha256=digest(target), bytes=target.stat().st_size,
             models=16 if kind == "FINAL_REPLAY_MODELS" else 0,
             legacy_models="旧联合八格留在原实验，不重复拷贝；核查结果和源记录在DATAONLY。", time=now()))
        print("[结果包]", target, flush=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--resume", action="store_true")
    parser.add_argument("--retry-failed", action="store_true")
    parser.add_argument("--device", choices=("cpu", "cuda"), default="cuda")
    parser.add_argument("--eval-device", choices=("cpu",), default="cpu")
    parser.add_argument("--wall-hours", type=float, default=18.)
    parser.add_argument("--min-free-gib", type=float, default=15.)
    parser.add_argument("--phase", choices=("all", "train", "eval", "pack"), default="all")
    parser.add_argument("--plan", action="store_true")
    parser.add_argument("--worker", choices=("train", "eval"))
    parser.add_argument("--task", type=Path)
    parser.add_argument("--root", type=Path)
    args = parser.parse_args()
    task_list = tasks()
    if args.plan:
        print(json.dumps(dict(tasks=task_list, new_steps=NEW_STEPS, step_cap=CAP,
                              audit_only_legacy=legacy_ids(), steps_per_model=STEPS,
                              expected_hours="约8—11小时粗估；只补16格，不为用满18小时追加训练。"), ensure_ascii=False, indent=2))
        return
    if not 0 < args.wall_hours <= 18:
        raise RuntimeError("本套单会话最多18小时；改变会话时限不缩短单格训练步数")
    root = (args.root or PROJECT / "serial_runs" / ROOT_NAME).absolute()
    expected = PROJECT / "serial_runs" / ROOT_NAME
    if root.is_symlink() or root.resolve() != expected.resolve() or root.parent.is_symlink():
        raise RuntimeError("只允许写入本套独立实验目录")
    stage, module = runtime()
    if args.worker:
        if args.task is None or args.task.is_symlink() or not args.task.resolve().is_relative_to(root.resolve()):
            raise RuntimeError("子任务说明路径不合法")
        job = read(args.task)
        task, config = job["task"], job["config"]
        if task not in task_list:
            raise RuntimeError("子任务不属于本次16格STIN补齐")
        if args.worker == "train":
            module.attr_train(task, root, config)
        else:
            evaluate(stage, module, task, root, config)
        return
    root.mkdir(parents=True, exist_ok=True)
    lock = stage.take_lock(root)
    started = time.monotonic()
    deadline = started + args.wall_hours * 3600 - 90
    status = "PARTIAL"
    try:
        prior = read(root / "SUITE_PLAN.json")
        if prior and not args.resume and args.phase != "pack":
            raise RuntimeError("目录已有本套结果，请加--resume，不覆盖重训")
        if prior and prior["script_sha256"] != digest(__file__):
            raise RuntimeError("代码hash改变，不混入既有训练")
        if not prior and (root / "cells").exists() and any((root / "cells").iterdir()):
            raise RuntimeError("已有cell缺科学合同，保留待查")
        legacy = audit_legacy(PROJECT / "serial_runs" / LEGACY_NAME,
                              PROJECT / "experiment_archives" / f"{LEGACY_NAME}_DATAONLY.tar.gz")
        save(root / "LEGACY_JOINT_AUDIT.json", legacy)
        print(f"[旧E1联合STIN] 完整记录 {legacy['complete']}/8；最终模型配套 {legacy['final_models_present']}/8；不重训", flush=True)
        native = module.materialize_source(root)
        bank = module.gap_bank(root, native)
        confirmation = stage.make_confirmation_bank(module, root, native)
        for entry in confirmation:
            entry["role"] = "既有6501—6504额外验证顺序，已查看，不是未触碰最终测试。"
        save(root / "NEW_CONFIRMATION_BANK.json", confirmation)
        config = dict(version=VERSION, device=args.device, eval_device="cpu",
                      trace=str(native / "train_data/passengers_300.csv"), bank=bank, sealed_bank=confirmation,
                      train_horizon=500, eval_horizon=600, actual_steps=STEPS, requested_steps=STEPS,
                      resume=args.resume, retry_failed=args.retry_failed, timeout_hours=3.)
        contract = dict(version=VERSION, script_sha256=digest(__file__), sealed_stage_sha256=SEALED_STAGE_SHA,
                        stin_sha256=STIN_SHA, tasks=task_list, planned_actual_budget=NEW_STEPS, budget_cap=CAP,
                        config={k: v for k, v in config.items() if k not in ("resume", "retry_failed")},
                        primary="每模型末20%固定存档×4301—4304；6501—6504是已查看的额外验证顺序，不称未触碰最终测试。",
                        scope="仅E0-LQ/E1-LQ开关×四种子；旧E1-J3八格只读核验，不新增方法或机场规模。")
        if prior and prior != contract:
            raise RuntimeError("续跑的科学合同改变")
        if not prior:
            save(root / "SUITE_PLAN.json", contract)
        save(root / "TASK_REGISTRY.json", task_list)
        for task in task_list:
            save(root / "cells" / task["id"] / "TASK.json", task)
        if args.phase != "pack":
            resource_check(root, args.device, args.min_free_gib)
            for i, task in enumerate(task_list, 1):
                if time.monotonic() >= deadline or (root / "STOP_REQUESTED").exists():
                    break
                folder = root / "cells" / task["id"]
                try:
                    if train_complete(folder, task) and eval_complete(folder):
                        print(f"[已有完整，跳过 {i}/16]", task["id"], flush=True)
                        continue
                    resource_check(root, args.device, args.min_free_gib)
                    if args.phase in ("all", "train") and not train_complete(folder, task):
                        print(f"[补训练 {i}/16]", task["id"], flush=True)
                        if not stage.child("train", task, root, config, deadline):
                            aggregate(module, root, task_list, legacy)
                            continue
                    if args.phase in ("all", "eval") and train_complete(folder, task) and not eval_complete(folder):
                        print(f"[补评估 {i}/16]", task["id"], flush=True)
                        stage.child("eval", task, root, config, deadline)
                except Exception:
                    save(folder / f"FAILED_parent_{time.time_ns()}.json", dict(traceback=traceback.format_exc(), time=now()))
                    print("[单格保留并继续]", task["id"], flush=True)
                aggregate(module, root, task_list, legacy)
        progress = aggregate(module, root, task_list, legacy)
        new_complete = progress["evaluated"] == 16 and progress["failed"] == 0
        status = "COMPLETE" if new_complete and legacy["complete"] == 8 else "PARTIAL"
        save(root / "END.json", dict(status=status, new_single_complete=new_complete, progress=progress,
             wall_seconds=time.monotonic() - started, legacy_joint_retrained=False,
             warning="旧联合记录缺失只报告，不为填表自动多训八格；旧模型缺失不等于旧实验未完成。", time=now()))
        pack(root, task_list, legacy, new_complete)
        print("[结束]", status, progress, flush=True)
    finally:
        save(root / "RUNNING.json", dict(phase="complete" if status == "COMPLETE" else "idle_partial",
                                         task=None, pid=None, time=now()))
        lock.close()


if __name__ == "__main__":
    main()
